<?php
namespace App\Services\Payment;
use App\Models\Order; use Illuminate\Support\Facades\Http; use Illuminate\Validation\ValidationException;
class MidtransPaymentGateway implements PaymentGatewayInterface { public function create(Order $order): array { $key=config('services.midtrans.server_key'); if(!$key) throw ValidationException::withMessages(['payment'=>['Midtrans server key belum dikonfigurasi.']]); $url=config('services.midtrans.is_production')?'https://app.midtrans.com/snap/v1/transactions':'https://app.sandbox.midtrans.com/snap/v1/transactions'; 
        $midtransOrderId = $order->number . '-' . time();
        $r=Http::withBasicAuth($key,'')->post($url,['transaction_details'=>['order_id'=>$midtransOrderId,'gross_amount'=>(int)$order->grand_total],'customer_details'=>['first_name'=>$order->recipient_name,'phone'=>$order->phone]]); $r->throw(); return ['reference'=>$midtransOrderId,'status'=>'pending','token'=>$r->json('token'),'redirect_url'=>$r->json('redirect_url')]; } public function verify(array $payload): bool { $key=config('services.midtrans.server_key'); if(!$key||!isset($payload['signature_key'],$payload['order_id'],$payload['status_code'],$payload['gross_amount'])) return false; return hash_equals(hash('sha512',$payload['order_id'].$payload['status_code'].$payload['gross_amount'].$key),$payload['signature_key']); } }
